style:
html, body {
  margin: 0;
  padding: 0;
  background: transparent;
  height: 100vh;
  width: 100vw;
  display: flex;
  justify-content: center;
  align-items: center;
}

.logo-row {
  display: flex;
  justify-content: space-between; /* equal spacing between logos */
  align-items: center;
  width: 90vw; /* container width */
  background: transparent;
}

.logo-row img {
  height: 60px;
  width: auto;
  background: transparent;
  user-select: none;
  pointer-events: auto;
  display: block;
  flex-shrink: 0;
  cursor: pointer;
  transition: 
    filter 0.3s ease, 
    transform 0.3s ease;
  margin: 0; /* remove margins */
}

/* Grayscale all except Unreal */
.logo-row img:not(.unreal) {
  filter: grayscale(100%);
}

/* Unreal logo inverted always */
.logo-row img.unreal {
  filter: invert(1);
}

/* On hover, remove grayscale from all except Unreal, add scale */
.logo-row img:not(.unreal):hover {
  filter: none;
  transform: scale(1.1);
}

/* Unreal logo hover: scale, keep inverted */
.logo-row img.unreal:hover {
  transform: scale(1.1);
}

